import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  drawerBackdropClassName,
  drawerCloseClassName,
  drawerContentClassName,
  drawerDescriptionClassName,
  drawerPopupClassName,
  drawerPortalClassName,
  drawerRootClassName,
  drawerTitleClassName,
  drawerTriggerClassName,
  drawerViewportClassName,
} from "./view";

export {
  drawerBackdropClassName,
  drawerCloseClassName,
  drawerContentClassName,
  drawerDescriptionClassName,
  drawerPopupClassName,
  drawerPortalClassName,
  drawerRootClassName,
  drawerTitleClassName,
  drawerTriggerClassName,
  drawerViewportClassName,
} from "./view";

export type DrawerStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: DrawerStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  onClick: ParentMessage;
  children: readonly Html[];
  className?: string | undefined;
  style?: DrawerStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  className?: string | undefined;
  style?: DrawerStyle | undefined;
}>;

export type PartViewConfig = Readonly<{
  id?: string | undefined;
  children: readonly Html[];
  className?: string | undefined;
  style?: DrawerStyle | undefined;
}>;

export type PopupViewConfig = Readonly<{
  titleId: string;
  descriptionId: string;
  children: readonly Html[];
  className?: string | undefined;
  style?: DrawerStyle | undefined;
}>;

export type CloseViewConfig<ParentMessage> = Readonly<{
  onClick: ParentMessage;
  children: readonly Html[];
  className?: string | undefined;
  style?: DrawerStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const partView = <ParentMessage>(
  tagName: "div" | "h2" | "p",
  baseClassName: string,
  { id, children, className, style }: PartViewConfig
): Html => {
  const h = html<ParentMessage>();
  const attributes = [
    ...(id === undefined ? [] : [h.Id(id)]),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(classNames(baseClassName, className)),
  ];

  if (tagName === "h2") {
    return h.h2(attributes, children);
  }

  if (tagName === "p") {
    return h.p(attributes, children);
  }

  return h.div(attributes, children);
};

export const rootView = <ParentMessage>(config: RootViewConfig): Html =>
  partView<ParentMessage>("div", drawerRootClassName, config);

export const triggerView = <ParentMessage>({
  onClick,
  children,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.OnClick(onClick),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(drawerTriggerClassName, className)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  className,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Hidden(true)], []);
  }

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(drawerPortalClassName, className)),
    ],
    children
  );
};

export const backdropView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("div", drawerBackdropClassName, config);

export const viewportView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("div", drawerViewportClassName, config);

export const popupView = <ParentMessage>({
  titleId,
  descriptionId,
  children,
  className,
  style,
}: PopupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.aside(
    [
      h.Attribute("role", "dialog"),
      h.Attribute("aria-modal", "true"),
      h.Attribute("aria-labelledby", titleId),
      h.Attribute("aria-describedby", descriptionId),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(drawerPopupClassName, className)),
    ],
    children
  );
};

export const contentView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("div", drawerContentClassName, config);

export const titleView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("h2", drawerTitleClassName, config);

export const descriptionView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("p", drawerDescriptionClassName, config);

export const closeView = <ParentMessage>({
  onClick,
  children,
  className,
  style,
}: CloseViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.OnClick(onClick),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(drawerCloseClassName, className)),
    ],
    children
  );
};

export const drawerRootClassName = "contents";

export const drawerTriggerClassName =
  "inline-flex h-10 w-fit items-center justify-center rounded-md bg-gray-950 px-4 text-sm font-medium text-white transition-colors hover:bg-gray-800";

export const drawerPortalClassName = "fixed inset-0 z-50";

export const drawerBackdropClassName = "fixed inset-0 bg-black/30";

export const drawerViewportClassName = "fixed inset-0 flex justify-end";

export const drawerPopupClassName =
  "grid h-full w-full max-w-sm content-start gap-4 bg-white p-6 shadow-xl";

export const drawerContentClassName = "grid gap-3";

export const drawerTitleClassName = "text-lg font-semibold text-gray-950";

export const drawerDescriptionClassName = "text-sm leading-6 text-gray-600";

export const drawerCloseClassName =
  "inline-flex h-9 w-fit items-center justify-center rounded-md border border-gray-300 bg-white px-3 text-sm font-medium text-gray-900 hover:bg-gray-50";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Drawer from ".";

const view = (open: boolean) => {
  const h = html<boolean>();

  return Drawer.rootView<boolean>({
    children: [
      Drawer.triggerView({
        onClick: true,
        children: [h.span([], ["Open drawer"])],
      }),
      Drawer.portalView({
        open,
        children: [
          Drawer.backdropView({ children: [] }),
          Drawer.viewportView({
            children: [
              Drawer.popupView({
                titleId: "title",
                descriptionId: "description",
                children: [
                  Drawer.titleView({
                    id: "title",
                    children: [h.span([], ["Drawer"])],
                  }),
                  Drawer.descriptionView({
                    id: "description",
                    children: [h.span([], ["Drawer description"])],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Base UI Drawer registry component", () => {
  test("opens an aria-labelled dialog drawer", () => {
    Scene.scene(
      {
        update: (_model: boolean, message: boolean) => [message, []] as const,
        view,
      },
      Scene.with(false),
      Scene.expect(Scene.role("dialog", { name: "Drawer" })).not.toExist(),
      Scene.click(Scene.role("button", { name: "Open drawer" })),
      Scene.expect(Scene.role("dialog", { name: "Drawer" })).toHaveAttr(
        "aria-describedby",
        "description"
      )
    );
  });

  test("exports Base UI drawer class hooks", () => {
    expect(Drawer.drawerPopupClassName).toContain("shadow");
    expect(Drawer.drawerViewportClassName).toContain("justify-end");
  });
});
